import React from 'react';

function UserList({ users = [] }) {
  return (
    <div>
      <h2>User List</h2>

      {users.map((user) => (
        <p key={user.id}>
          Name: {user.name} Age: {user.age}
        </p>
      ))}
    </div>
  );
}

export default UserList;
